    constructor(C _c) { c = _c; }

    function run() public payable {
        bool reverted;
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted == (c.owner() == address(this)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 value) public {
        require(to != address(0), "recipient must be nonzero");
        require(value <= c.totalSupply(), "value must not exceed total supply");
        require(to != address(this), "recipient must not be the test contract");

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.balanceOf(address(this)) == senderBefore - value);
            assert(c.balanceOf(to) == recipientBefore + value);
        } else {
            assert(c.balanceOf(address(this)) == senderBefore);
            assert(c.balanceOf(to) == recipientBefore);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount <= c.totalSupply(), "amount exceeds total supply");

        uint256 totalBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 expectedAfter = totalBefore - amount;

        bool reverted;
        try c.burn(amount) returns (bool success) {
            reverted = !success;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.totalSupply() == expectedAfter && c.balanceOf(address(this)) == balanceBefore - amount);
        } else {
            assert(c.totalSupply() == totalBefore && c.balanceOf(address(this)) == balanceBefore);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 burnAmount) public {
        require(true);

        uint256 ownerBalanceBefore = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();

        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 ownerBalanceAfter = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();

        if (burnAmount <= ownerBalanceBefore) {
            assert(!reverted
                && ownerBalanceAfter == ownerBalanceBefore - burnAmount
                && totalSupplyAfter == totalSupplyBefore - burnAmount);
        } else {
            assert(reverted
                && ownerBalanceAfter == ownerBalanceBefore
                && totalSupplyAfter == totalSupplyBefore);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 mintedAmount) public {
        require(target != address(0));

        uint256 targetBefore = c.balanceOf(target);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 targetAfter = c.balanceOf(target);
        uint256 supplyAfter = c.totalSupply();

        assert(reverted && targetAfter == targetBefore && supplyAfter == supplyBefore);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 value) public {
        require(to != address(0));
        require(to != address(this));
        require(value <= c.totalSupply());
        require(value <= c.balanceOf(address(this)));

        uint256 beforeBalanceThis = c.balanceOf(address(this));
        uint256 beforeBalanceTo = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalanceThis = c.balanceOf(address(this));
        uint256 afterBalanceTo = c.balanceOf(to);

        if (reverted) {
            assert(afterBalanceThis == beforeBalanceThis && afterBalanceTo == beforeBalanceTo);
        } else {
            assert(afterBalanceThis + afterBalanceTo == beforeBalanceThis + beforeBalanceTo + value);
        }
    }

    receive() external payable {}
}
